    'scatter',
    'dualAxis',
    // other
    'funnel',
    'heatmap',
  ]

  const changeChartType = (c) => () => {
    setChartType(c)
  }

  useEffect(() => {
    if (!ref.current) {
      return
    }

    const vseed: VSeed = {
      chartType,
      dataset: [
        { date: '2019', profit: 10, sales: 100 },
