          <button onClick={handlePrev} style={btnStyle} title="Trước">
            <svg viewBox="0 0 24 24" style={iconStyle}>
              <path d="M15.41 7.41L14 6l-6 6 6 6 1.41-1.41L10.83 12z" />
            </svg>
          </button>

          <select
            style={{
              flex: 1,
              height: '32px',
              border: '1px solid #e2e8f0',
              borderRadius: '6px',
              padding: '0 8px',
              outline: 'none',
            }}
            value={currentIndex}
            onChange={(e) => setCurrentIndex(Number(e.target.value))}
          >
            {order.map((d, i) => (
              <option key={i} value={i}>
                {d}
              </option>
            ))}
          </select>

          <button onClick={handleNext} style={btnStyle} title="Tiếp">
            <svg viewBox="0 0 24 24" style={iconStyle}>
              <path d="M10 6L8.59 7.41 13.17 12l-4.58 4.59L10 18l6-6z" />
            </svg>
          </button>

          <button onClick={togglePlay} style={{ ...btnStyle, minWidth: 80 }} title={isPlaying ? 'Pause' : 'Play'}>
            {isPlaying ? (
              <>
                <svg viewBox="0 0 24 24" style={{ ...iconStyle, marginRight: 4 }}>
                  <path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z" />
                </svg>
                Pause
              </>
            ) : (
              <>
                <svg viewBox="0 0 24 24" style={{ ...iconStyle, marginRight: 4 }}>
                  <path d="M8 5v14l11-7z" />
                </svg>
                Play
              </>
            )}
          </button>
        </div>

        {/* Hàng 2: Thanh tiến trình */}
        <div style={{ display: 'flex', alignItems: 'center' }}>
          <input
            type="range"
            min="0"
            max={order.length - 1}
            value={currentIndex}
            onChange={(e) => setCurrentIndex(Number(e.target.value))}
            style={{ width: '100%', cursor: 'pointer' }}
          />
        </div>
      </div>
      <div ref={ref} style={{ height: 260, width: '100%' }} />
    </div>
  )
})

